push.css:
.fxs .gw{--pushA:#C99A3E;--pushB:#5E4019;--pushC:#E9C46A;--rim:#E9C46A;--rimD:#4E2810}
.fxs .push.gw{--pr:14px;background:none;border-radius:14px;box-shadow:none;filter:drop-shadow(0 8px 0 rgba(46,30,16,.6)) drop-shadow(0 18px 24px rgba(0,0,0,.4))}
.fxs .push.gw span{top:2px;font:800 40px/1 "Kaisei Tokumin",serif;letter-spacing:.06em;color:#4E2810;text-shadow:0 1.5px 0 #FFE7A6,0 -1px 0 #5E4019}
.fxs .push.gw::after{inset:-24px -30px -18px;top:-74px;border-radius:30px;border-color:rgba(233,196,106,.85)}
.fxs .gw .gwf{position:absolute;left:-40px;top:-56px;width:280px;height:160px;pointer-events:none;font-style:normal}
.fxs .gw .gwf svg{display:block;width:280px;height:160px;overflow:visible}
.fxs .gw .gwd{position:absolute;left:-40px;top:-60px;width:280px;height:180px;pointer-events:none;z-index:3;font-style:normal}
.fxs .gw .gwd svg{display:block;width:280px;height:180px;overflow:visible}
.fxs .gw .gwfg{transform-box:fill-box;transform-origin:50% 50%;animation:fxgwfRot 6s linear infinite}
.fxs .gw .gwfg.r{animation:fxgwfRotR 4.7s linear infinite}
@keyframes fxgwfRot{to{transform:rotate(360deg)}}
@keyframes fxgwfRotR{to{transform:rotate(-360deg)}}
.fxs .gw .gwfn{transform-box:view-box;animation:fxgwfNd 2.4s ease-in-out infinite}
@keyframes fxgwfNd{0%,100%{transform:rotate(-24deg)}45%{transform:rotate(16deg)}60%{transform:rotate(6deg)}75%{transform:rotate(20deg)}}
.fxs .gw .gwst{transform-box:view-box;opacity:0;animation:fxgwfSt 3.6s ease-out infinite}
@keyframes fxgwfSt{0%{opacity:0;transform:scale(.4) translateY(4px)}12%{opacity:.9}60%{opacity:0;transform:scale(1.25) translateY(-14px)}100%{opacity:0;transform:scale(1.25) translateY(-14px)}}
.fxs .pshadow.gw{width:230px}
.fxs .tap.gw{font-family:"Kaisei Tokumin",serif;font-weight:800;color:#F0C76A;letter-spacing:.12em;text-shadow:0 2px 0 #2E2420,0 0 10px rgba(233,196,106,.5)}
.fxs .pressed.gw{border-radius:14px;background:#C99A3E;box-shadow:0 0 0 4px #B5683A,0 7px 0 4px #4E2810;animation-name:fxgwPress,fxfxH}
@keyframes fxgwPress{0%{transform:scale(1)}22%{transform:scale(.9)}45%{transform:scale(1.07)}100%{transform:scale(1.45);opacity:0}}
@media (prefers-reduced-motion:reduce){.fxs .gw .gwfg,.fxs .gw .gwfn,.fxs .gw .gwst{animation:none}
.fxs .gw .gwst,.fxs .clips.gw{display:none}}
